CREATE TABLE IF NOT EXISTS "contacts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The identity of a contact. Stored lowercased; uniqueness here is what makes suppression and deduplication tractable.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Used for merge tags. Null is normal and templates must render without it.
	"first_name" VARCHAR(120),
	-- Second half of the display name.
	"last_name" VARCHAR(120),
	-- subscribed | unsubscribed | bounced | complained | cleaned. Global state, independent of any single list.
	"status" VARCHAR(20) NOT NULL DEFAULT 'subscribed',
	-- Values for the custom fields defined in custom_fields. JSONB rather than an EAV table because a contact has tens of attributes and a database has tens of millions of contacts.
	"attributes" JSONB,
	-- IANA zone used for send-time optimisation. Null means send in the campaign timezone.
	"timezone" VARCHAR(64),
	-- signup_form | import | api | checkout. Kept because a compliance complaint asks where consent came from, not whether a flag is true.
	"consent_source" VARCHAR(40),
	-- When consent was recorded. The proof that matters under GDPR and CAN-SPAM.
	"consent_at" TIMESTAMP,
	-- When the contact first entered the database.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "contacts" IS 'The person. Global status lives here and list membership lives in list_subscriptions, because unsubscribing from one newsletter is not the same act as never wanting to hear from the brand again.';
COMMENT ON COLUMN "contacts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "contacts"."email" IS 'The identity of a contact. Stored lowercased; uniqueness here is what makes suppression and deduplication tractable.';
COMMENT ON COLUMN "contacts"."first_name" IS 'Used for merge tags. Null is normal and templates must render without it.';
COMMENT ON COLUMN "contacts"."last_name" IS 'Second half of the display name.';
COMMENT ON COLUMN "contacts"."status" IS 'subscribed | unsubscribed | bounced | complained | cleaned. Global state, independent of any single list.';
COMMENT ON COLUMN "contacts"."attributes" IS 'Values for the custom fields defined in custom_fields. JSONB rather than an EAV table because a contact has tens of attributes and a database has tens of millions of contacts.';
COMMENT ON COLUMN "contacts"."timezone" IS 'IANA zone used for send-time optimisation. Null means send in the campaign timezone.';
COMMENT ON COLUMN "contacts"."consent_source" IS 'signup_form | import | api | checkout. Kept because a compliance complaint asks where consent came from, not whether a flag is true.';
COMMENT ON COLUMN "contacts"."consent_at" IS 'When consent was recorded. The proof that matters under GDPR and CAN-SPAM.';
COMMENT ON COLUMN "contacts"."created_at" IS 'When the contact first entered the database.';

CREATE INDEX "idx_contacts_status"
ON "contacts" ("status");

CREATE TABLE IF NOT EXISTS "custom_fields" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Attribute name as used in contacts.attributes and in merge tags.
	"key" VARCHAR(60) NOT NULL UNIQUE,
	-- Human label shown in the segment builder and import mapper.
	"label" VARCHAR(120) NOT NULL,
	-- text | number | date | boolean | choice. Drives which operators the segment builder offers.
	"field_type" VARCHAR(20) NOT NULL DEFAULT 'text',
	-- Allowed values for choice fields. Null for every other type.
	"options" JSONB,
	-- Enforced at import and signup, not by the database, since the values live in a JSON document.
	"is_required" BOOLEAN NOT NULL DEFAULT false,
	-- When the field was defined.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "custom_fields" IS 'Definitions only; the values are in contacts.attributes. Splitting them this way gives the segment builder a typed vocabulary to validate against without paying for a join per attribute per contact.';
COMMENT ON COLUMN "custom_fields"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "custom_fields"."key" IS 'Attribute name as used in contacts.attributes and in merge tags.';
COMMENT ON COLUMN "custom_fields"."label" IS 'Human label shown in the segment builder and import mapper.';
COMMENT ON COLUMN "custom_fields"."field_type" IS 'text | number | date | boolean | choice. Drives which operators the segment builder offers.';
COMMENT ON COLUMN "custom_fields"."options" IS 'Allowed values for choice fields. Null for every other type.';
COMMENT ON COLUMN "custom_fields"."is_required" IS 'Enforced at import and signup, not by the database, since the values live in a JSON document.';
COMMENT ON COLUMN "custom_fields"."created_at" IS 'When the field was defined.';

CREATE TABLE IF NOT EXISTS "lists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name, e.g. "Weekly digest".
	"name" VARCHAR(160) NOT NULL,
	-- Default sender name for campaigns on this list.
	"from_name" VARCHAR(120) NOT NULL,
	-- Default sender address. Must be on a verified domain.
	"from_email" VARCHAR(320) NOT NULL,
	-- Whether a confirmation click is required. Deliverability is mostly decided by this one setting.
	"double_opt_in" BOOLEAN NOT NULL DEFAULT true,
	-- Archived lists stop accepting sends but keep their subscription history.
	"archived_at" TIMESTAMP,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lists" IS 'An explicit audience a person joined, as opposed to a segment, which is a query. The distinction is legal as much as technical: consent is given to a list.';
COMMENT ON COLUMN "lists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lists"."name" IS 'Display name, e.g. "Weekly digest".';
COMMENT ON COLUMN "lists"."from_name" IS 'Default sender name for campaigns on this list.';
COMMENT ON COLUMN "lists"."from_email" IS 'Default sender address. Must be on a verified domain.';
COMMENT ON COLUMN "lists"."double_opt_in" IS 'Whether a confirmation click is required. Deliverability is mostly decided by this one setting.';
COMMENT ON COLUMN "lists"."archived_at" IS 'Archived lists stop accepting sends but keep their subscription history.';
COMMENT ON COLUMN "lists"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "list_subscriptions" (
	-- List joined. Part of the composite key.
	"list_id" BIGINT,
	-- Contact joining. Part of the composite key, which makes double subscription impossible.
	"contact_id" BIGINT,
	-- pending | subscribed | unsubscribed. pending is the unconfirmed half of double opt-in.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Where this particular subscription came from, which can differ from the contact consent_source.
	"source" VARCHAR(40),
	-- Confirmation time. Null while pending.
	"subscribed_at" TIMESTAMP,
	-- Kept rather than deleted so re-subscription and churn are measurable.
	"unsubscribed_at" TIMESTAMP,
	PRIMARY KEY("list_id", "contact_id")
);

COMMENT ON TABLE "list_subscriptions" IS 'Per-list consent. The row is never deleted on unsubscribe: proving that someone opted out and when is exactly the record a regulator asks for.';
COMMENT ON COLUMN "list_subscriptions"."list_id" IS 'List joined. Part of the composite key.';
COMMENT ON COLUMN "list_subscriptions"."contact_id" IS 'Contact joining. Part of the composite key, which makes double subscription impossible.';
COMMENT ON COLUMN "list_subscriptions"."status" IS 'pending | subscribed | unsubscribed. pending is the unconfirmed half of double opt-in.';
COMMENT ON COLUMN "list_subscriptions"."source" IS 'Where this particular subscription came from, which can differ from the contact consent_source.';
COMMENT ON COLUMN "list_subscriptions"."subscribed_at" IS 'Confirmation time. Null while pending.';
COMMENT ON COLUMN "list_subscriptions"."unsubscribed_at" IS 'Kept rather than deleted so re-subscription and churn are measurable.';

CREATE INDEX "idx_list_subs_contact_status"
ON "list_subscriptions" ("contact_id", "status");

CREATE TABLE IF NOT EXISTS "segments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name, e.g. "Opened in the last 30 days, not purchased".
	"name" VARCHAR(160) NOT NULL,
	-- Optional scope. Null means the segment evaluates across every contact.
	"list_id" BIGINT,
	-- The filter tree: nested any/all groups of field, operator and value. JSON because real segment rules nest, and a flat rules table cannot express (A and B) or C.
	"rules" JSONB NOT NULL,
	-- Dynamic segments re-evaluate at send time; a static one is frozen to the members captured when it was built.
	"is_dynamic" BOOLEAN NOT NULL DEFAULT true,
	-- Cached size for the UI. Stale by design; the send path re-evaluates rather than trusting it.
	"member_count" INTEGER,
	-- When the cached count was produced.
	"last_evaluated_at" TIMESTAMP,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "segments" IS 'A saved query over contacts, not a membership table. Materialising members would require invalidating on every attribute change and every open, which is more write traffic than the engagement data itself.';
COMMENT ON COLUMN "segments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "segments"."name" IS 'Display name, e.g. "Opened in the last 30 days, not purchased".';
COMMENT ON COLUMN "segments"."list_id" IS 'Optional scope. Null means the segment evaluates across every contact.';
COMMENT ON COLUMN "segments"."rules" IS 'The filter tree: nested any/all groups of field, operator and value. JSON because real segment rules nest, and a flat rules table cannot express (A and B) or C.';
COMMENT ON COLUMN "segments"."is_dynamic" IS 'Dynamic segments re-evaluate at send time; a static one is frozen to the members captured when it was built.';
COMMENT ON COLUMN "segments"."member_count" IS 'Cached size for the UI. Stale by design; the send path re-evaluates rather than trusting it.';
COMMENT ON COLUMN "segments"."last_evaluated_at" IS 'When the cached count was produced.';
COMMENT ON COLUMN "segments"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "campaigns" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Internal name; the subject line lives on the variant.
	"name" VARCHAR(200) NOT NULL,
	-- Audience list. Null when the audience is defined purely by a segment.
	"list_id" BIGINT,
	-- Optional filter applied on top of the list.
	"segment_id" BIGINT,
	-- draft | scheduled | sending | sent | paused | canceled. sending is a real state that can last hours.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- one_off | ab_test | automation. An automation campaign is triggered per contact rather than blasted.
	"send_type" VARCHAR(20) NOT NULL DEFAULT 'one_off',
	-- open_rate | click_rate | conversion. Null when the campaign is not a test.
	"ab_winner_metric" VARCHAR(20),
	-- How long the test runs before the winner is sent to the remaining audience.
	"ab_decision_after_minutes" INTEGER,
	-- Requested start. Null for immediate or triggered sends.
	"scheduled_at" TIMESTAMP,
	-- When the first send row was queued.
	"started_at" TIMESTAMP,
	-- When the last send row left the queue.
	"completed_at" TIMESTAMP,
	-- IANA zone for a scheduled local-time send.
	"timezone" VARCHAR(64),
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "campaigns" IS 'The campaign is the plan; the content is in campaign_variants. Keeping subject and body off this row is what makes an A/B test one campaign rather than two campaigns you have to compare by hand.';
COMMENT ON COLUMN "campaigns"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "campaigns"."name" IS 'Internal name; the subject line lives on the variant.';
COMMENT ON COLUMN "campaigns"."list_id" IS 'Audience list. Null when the audience is defined purely by a segment.';
COMMENT ON COLUMN "campaigns"."segment_id" IS 'Optional filter applied on top of the list.';
COMMENT ON COLUMN "campaigns"."status" IS 'draft | scheduled | sending | sent | paused | canceled. sending is a real state that can last hours.';
COMMENT ON COLUMN "campaigns"."send_type" IS 'one_off | ab_test | automation. An automation campaign is triggered per contact rather than blasted.';
COMMENT ON COLUMN "campaigns"."ab_winner_metric" IS 'open_rate | click_rate | conversion. Null when the campaign is not a test.';
COMMENT ON COLUMN "campaigns"."ab_decision_after_minutes" IS 'How long the test runs before the winner is sent to the remaining audience.';
COMMENT ON COLUMN "campaigns"."scheduled_at" IS 'Requested start. Null for immediate or triggered sends.';
COMMENT ON COLUMN "campaigns"."started_at" IS 'When the first send row was queued.';
COMMENT ON COLUMN "campaigns"."completed_at" IS 'When the last send row left the queue.';
COMMENT ON COLUMN "campaigns"."timezone" IS 'IANA zone for a scheduled local-time send.';
COMMENT ON COLUMN "campaigns"."created_at" IS 'Creation time.';

CREATE INDEX "idx_campaigns_status_scheduled"
ON "campaigns" ("status", "scheduled_at");

CREATE TABLE IF NOT EXISTS "campaign_variants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent campaign.
	"campaign_id" BIGINT NOT NULL,
	-- A, B, C. A non-test campaign has exactly one variant, labelled A, so the send path has no special case.
	"label" VARCHAR(8) NOT NULL DEFAULT 'A',
	-- Subject line, the thing most often tested.
	"subject" VARCHAR(255) NOT NULL,
	-- Preview text shown after the subject in most clients.
	"preheader" VARCHAR(255),
	-- Overrides the list default, since sender name is itself a testable variable.
	"from_name" VARCHAR(120),
	-- Rendered HTML with merge tags left in place; personalisation happens per recipient at send time.
	"html_body" TEXT NOT NULL,
	-- Plain-text alternative. Its absence measurably hurts deliverability.
	"text_body" TEXT,
	-- Share of the test audience this variant gets. Percentages across a campaign must total 100.
	"traffic_percent" SMALLINT NOT NULL DEFAULT 100,
	-- Set once the decision window closes; the remaining audience is then sent this variant.
	"is_winner" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "campaign_variants" IS 'Every campaign has at least one variant. Making the single-variant case a degenerate A/B test means reporting, sending and rendering all read the same shape.';
COMMENT ON COLUMN "campaign_variants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "campaign_variants"."campaign_id" IS 'Parent campaign.';
COMMENT ON COLUMN "campaign_variants"."label" IS 'A, B, C. A non-test campaign has exactly one variant, labelled A, so the send path has no special case.';
COMMENT ON COLUMN "campaign_variants"."subject" IS 'Subject line, the thing most often tested.';
COMMENT ON COLUMN "campaign_variants"."preheader" IS 'Preview text shown after the subject in most clients.';
COMMENT ON COLUMN "campaign_variants"."from_name" IS 'Overrides the list default, since sender name is itself a testable variable.';
COMMENT ON COLUMN "campaign_variants"."html_body" IS 'Rendered HTML with merge tags left in place; personalisation happens per recipient at send time.';
COMMENT ON COLUMN "campaign_variants"."text_body" IS 'Plain-text alternative. Its absence measurably hurts deliverability.';
COMMENT ON COLUMN "campaign_variants"."traffic_percent" IS 'Share of the test audience this variant gets. Percentages across a campaign must total 100.';
COMMENT ON COLUMN "campaign_variants"."is_winner" IS 'Set once the decision window closes; the remaining audience is then sent this variant.';

CREATE UNIQUE INDEX "uq_variant_campaign_label"
ON "campaign_variants" ("campaign_id", "label");

CREATE TABLE IF NOT EXISTS "sends" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Campaign this delivery belongs to.
	"campaign_id" BIGINT NOT NULL,
	-- Variant actually rendered, so results can be attributed after the fact.
	"variant_id" BIGINT NOT NULL,
	-- Recipient.
	"contact_id" BIGINT NOT NULL,
	-- queued | sent | delivered | bounced | dropped | failed. Delivery is a state machine, not a boolean.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- Id from the sending gateway. The join key for asynchronous delivery webhooks.
	"provider_message_id" VARCHAR(255),
	-- When the row was created, which is also the throttle position.
	"queued_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Handoff to the gateway.
	"sent_at" TIMESTAMP,
	-- Accepted by the receiving server.
	"delivered_at" TIMESTAMP,
	-- hard | soft. Hard means the address is invalid and must be suppressed; soft is a temporary failure worth retrying.
	"bounce_type" VARCHAR(10),
	-- SMTP status such as 5.1.1. Kept because "bounced" alone cannot tell you whether your domain is in trouble.
	"bounce_code" VARCHAR(40),
	-- Denormalised counter maintained from send_events, so a campaign report does not aggregate a billion rows.
	"open_count" INTEGER NOT NULL DEFAULT 0,
	-- Same trade: the event rows remain the source of truth.
	"click_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sends" IS 'One row per recipient per campaign — by far the largest table you will own, and the reason this schema exists. It is the only place that can answer what a given person was actually sent, which variant, and what happened to it; the unique key on (campaign_id, contact_id) is what makes a retried batch idempotent instead of a double send.';
COMMENT ON COLUMN "sends"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sends"."campaign_id" IS 'Campaign this delivery belongs to.';
COMMENT ON COLUMN "sends"."variant_id" IS 'Variant actually rendered, so results can be attributed after the fact.';
COMMENT ON COLUMN "sends"."contact_id" IS 'Recipient.';
COMMENT ON COLUMN "sends"."status" IS 'queued | sent | delivered | bounced | dropped | failed. Delivery is a state machine, not a boolean.';
COMMENT ON COLUMN "sends"."provider_message_id" IS 'Id from the sending gateway. The join key for asynchronous delivery webhooks.';
COMMENT ON COLUMN "sends"."queued_at" IS 'When the row was created, which is also the throttle position.';
COMMENT ON COLUMN "sends"."sent_at" IS 'Handoff to the gateway.';
COMMENT ON COLUMN "sends"."delivered_at" IS 'Accepted by the receiving server.';
COMMENT ON COLUMN "sends"."bounce_type" IS 'hard | soft. Hard means the address is invalid and must be suppressed; soft is a temporary failure worth retrying.';
COMMENT ON COLUMN "sends"."bounce_code" IS 'SMTP status such as 5.1.1. Kept because "bounced" alone cannot tell you whether your domain is in trouble.';
COMMENT ON COLUMN "sends"."open_count" IS 'Denormalised counter maintained from send_events, so a campaign report does not aggregate a billion rows.';
COMMENT ON COLUMN "sends"."click_count" IS 'Same trade: the event rows remain the source of truth.';

CREATE INDEX "idx_sends_campaign_status"
ON "sends" ("campaign_id", "status");
CREATE INDEX "idx_sends_contact_queued"
ON "sends" ("contact_id", "queued_at");
CREATE UNIQUE INDEX "uq_sends_campaign_contact"
ON "sends" ("campaign_id", "contact_id");
CREATE INDEX "idx_sends_provider_message"
ON "sends" ("provider_message_id");

CREATE TABLE IF NOT EXISTS "send_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Delivery the event belongs to. Everything is attributed through this, so no event needs its own campaign or contact column.
	"send_id" BIGINT NOT NULL,
	-- open | click | complaint | unsubscribe | deferred. Deliveries and bounces update the send row instead, since they are terminal.
	"event_type" VARCHAR(20) NOT NULL,
	-- Provider timestamp, not receipt time — webhooks arrive out of order and hours late.
	"occurred_at" TIMESTAMP NOT NULL,
	-- Clicked link. Null for every other event type.
	"url" TEXT,
	-- Client string. The only signal you have for filtering machine opens from privacy proxies.
	"user_agent" VARCHAR(255),
	-- Source address, wide enough for IPv6. Used for geo reporting and bot detection.
	"ip_address" VARCHAR(45),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "send_events" IS 'Append-only engagement log, several rows per send. Opens are not deduplicated here on purpose: unique versus total opens is a reporting decision, and collapsing them on write throws away the data needed to make it later.';
COMMENT ON COLUMN "send_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "send_events"."send_id" IS 'Delivery the event belongs to. Everything is attributed through this, so no event needs its own campaign or contact column.';
COMMENT ON COLUMN "send_events"."event_type" IS 'open | click | complaint | unsubscribe | deferred. Deliveries and bounces update the send row instead, since they are terminal.';
COMMENT ON COLUMN "send_events"."occurred_at" IS 'Provider timestamp, not receipt time — webhooks arrive out of order and hours late.';
COMMENT ON COLUMN "send_events"."url" IS 'Clicked link. Null for every other event type.';
COMMENT ON COLUMN "send_events"."user_agent" IS 'Client string. The only signal you have for filtering machine opens from privacy proxies.';
COMMENT ON COLUMN "send_events"."ip_address" IS 'Source address, wide enough for IPv6. Used for geo reporting and bot detection.';

CREATE INDEX "idx_send_events_send_type"
ON "send_events" ("send_id", "event_type", "occurred_at");
CREATE INDEX "idx_send_events_type_time"
ON "send_events" ("event_type", "occurred_at");

CREATE TABLE IF NOT EXISTS "suppressions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Suppressed address. Stored as text, not a contact reference, so an address stays blocked even if the contact row is deleted.
	"email" VARCHAR(320) NOT NULL,
	-- Scope. Null means the address is suppressed globally across every list.
	"list_id" BIGINT,
	-- unsubscribe | hard_bounce | complaint | manual | global_block. Complaints and hard bounces are permanent; the others can be reversed.
	"reason" VARCHAR(24) NOT NULL,
	-- Delivery that triggered it, which is how you answer "why am I no longer receiving this?".
	"source_send_id" BIGINT,
	-- When suppression took effect.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "suppressions" IS 'The last check before any send, and the only table here keyed by address rather than by contact id. Suppression must outlive the contact record, survive a re-import of the same list, and apply even to a brand new signup with the same address.';
COMMENT ON COLUMN "suppressions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "suppressions"."email" IS 'Suppressed address. Stored as text, not a contact reference, so an address stays blocked even if the contact row is deleted.';
COMMENT ON COLUMN "suppressions"."list_id" IS 'Scope. Null means the address is suppressed globally across every list.';
COMMENT ON COLUMN "suppressions"."reason" IS 'unsubscribe | hard_bounce | complaint | manual | global_block. Complaints and hard bounces are permanent; the others can be reversed.';
COMMENT ON COLUMN "suppressions"."source_send_id" IS 'Delivery that triggered it, which is how you answer "why am I no longer receiving this?".';
COMMENT ON COLUMN "suppressions"."created_at" IS 'When suppression took effect.';

CREATE UNIQUE INDEX "uq_suppressions_email_scope"
ON "suppressions" ("email", "list_id");
CREATE INDEX "idx_suppressions_reason_time"
ON "suppressions" ("reason", "created_at");

CREATE TABLE IF NOT EXISTS "automations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name, e.g. "Welcome series".
	"name" VARCHAR(160) NOT NULL,
	-- list_subscribe | attribute_change | event | date_field | manual. The trigger is what distinguishes a drip from a campaign.
	"trigger_type" VARCHAR(30) NOT NULL,
	-- Parameters for the trigger: which list, which event name, which date offset.
	"trigger_config" JSONB,
	-- draft | active | paused. Pausing stops new enrolments but leaves existing ones in place.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- False by default, because the usual bug is a welcome series that greets the same person four times.
	"allow_re_enrolment" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "automations" IS 'A triggered sequence rather than a scheduled blast. Everything else in the schema is reused: its steps send real campaigns and produce real send rows.';
COMMENT ON COLUMN "automations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "automations"."name" IS 'Display name, e.g. "Welcome series".';
COMMENT ON COLUMN "automations"."trigger_type" IS 'list_subscribe | attribute_change | event | date_field | manual. The trigger is what distinguishes a drip from a campaign.';
COMMENT ON COLUMN "automations"."trigger_config" IS 'Parameters for the trigger: which list, which event name, which date offset.';
COMMENT ON COLUMN "automations"."status" IS 'draft | active | paused. Pausing stops new enrolments but leaves existing ones in place.';
COMMENT ON COLUMN "automations"."allow_re_enrolment" IS 'False by default, because the usual bug is a welcome series that greets the same person four times.';
COMMENT ON COLUMN "automations"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "automation_steps" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent sequence.
	"automation_id" BIGINT NOT NULL,
	-- Order within the sequence. Gaps are fine and make inserting a step cheap.
	"position" INTEGER NOT NULL,
	-- send | wait | condition | tag | exit. A sequence is a small program, and these are its instructions.
	"step_type" VARCHAR(20) NOT NULL,
	-- Campaign sent by a send step. Null for every other type.
	"campaign_id" BIGINT,
	-- Delay for a wait step, in minutes. Null for other types.
	"wait_minutes" INTEGER,
	-- Branch test for a condition step, in the same rule format as a segment.
	"condition_rules" JSONB,
	-- Explicit successor for a branch. Null means fall through to the next position.
	"next_step_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "automation_steps" IS 'The steps of the sequence. Modelling a wait as its own row rather than a delay column on a send is what lets a sequence branch, pause and be reordered without rewriting the schedule of everyone already in it.';
COMMENT ON COLUMN "automation_steps"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "automation_steps"."automation_id" IS 'Parent sequence.';
COMMENT ON COLUMN "automation_steps"."position" IS 'Order within the sequence. Gaps are fine and make inserting a step cheap.';
COMMENT ON COLUMN "automation_steps"."step_type" IS 'send | wait | condition | tag | exit. A sequence is a small program, and these are its instructions.';
COMMENT ON COLUMN "automation_steps"."campaign_id" IS 'Campaign sent by a send step. Null for every other type.';
COMMENT ON COLUMN "automation_steps"."wait_minutes" IS 'Delay for a wait step, in minutes. Null for other types.';
COMMENT ON COLUMN "automation_steps"."condition_rules" IS 'Branch test for a condition step, in the same rule format as a segment.';
COMMENT ON COLUMN "automation_steps"."next_step_id" IS 'Explicit successor for a branch. Null means fall through to the next position.';

CREATE UNIQUE INDEX "uq_automation_step_position"
ON "automation_steps" ("automation_id", "position");

CREATE TABLE IF NOT EXISTS "automation_enrolments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Sequence the contact is in.
	"automation_id" BIGINT NOT NULL,
	-- Enrolled contact.
	"contact_id" BIGINT NOT NULL,
	-- Step the contact is waiting on. Null once the sequence is finished.
	"current_step_id" BIGINT,
	-- active | completed | exited | failed. exited covers goal completion and manual removal.
	"state" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- When the scheduler should look at this row again. The single most important index in the automation engine.
	"next_run_at" TIMESTAMP,
	-- Entry time, used to enforce the re-enrolment rule.
	"enrolled_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the contact reached the end or exited.
	"completed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "automation_enrolments" IS 'One row per contact per run through a sequence, holding a program counter and a wake-up time. The scheduler is then a single indexed query for due rows rather than a nightly scan of every contact against every automation.';
COMMENT ON COLUMN "automation_enrolments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "automation_enrolments"."automation_id" IS 'Sequence the contact is in.';
COMMENT ON COLUMN "automation_enrolments"."contact_id" IS 'Enrolled contact.';
COMMENT ON COLUMN "automation_enrolments"."current_step_id" IS 'Step the contact is waiting on. Null once the sequence is finished.';
COMMENT ON COLUMN "automation_enrolments"."state" IS 'active | completed | exited | failed. exited covers goal completion and manual removal.';
COMMENT ON COLUMN "automation_enrolments"."next_run_at" IS 'When the scheduler should look at this row again. The single most important index in the automation engine.';
COMMENT ON COLUMN "automation_enrolments"."enrolled_at" IS 'Entry time, used to enforce the re-enrolment rule.';
COMMENT ON COLUMN "automation_enrolments"."completed_at" IS 'When the contact reached the end or exited.';

CREATE INDEX "idx_enrolments_due"
ON "automation_enrolments" ("state", "next_run_at");
CREATE INDEX "idx_enrolments_automation_contact"
ON "automation_enrolments" ("automation_id", "contact_id");

